const items = $input.all();
const out = [];
for (const item of items) {
  const b = item.json.body || item.json;
  const d = b.data || {};
  const key = d.key || {};
  if (key.fromMe) continue;
  const jid = key.remoteJid || '';
  if (!jid.endsWith('@s.whatsapp.net')) continue;
  const msg = d.message || {};
  const text = msg.conversation || (msg.extendedTextMessage && msg.extendedTextMessage.text) || '';
  if (!text.trim()) continue;
  out.push({ json: { phone: jid.replace('@s.whatsapp.net',''), text: text.trim(), name: d.pushName || 'عميل' } });
}
return out;

const chalets = $('جلب الشاليهات').first().json;
const bookings = $('جلب الحجوزات').first().json;
const msg = $('استخراج الرسالة').first().json;
const list = Array.isArray(chalets) ? chalets : [chalets];
const bks = Array.isArray(bookings) ? bookings : [bookings];
let txt = 'الشاليهات والأسعار:\n';
for (const c of list) {
  if (!c.active) continue;
  txt += `- ${c.name} (المعرف: ${c.id}) — وسط الأسبوع: ${c.weekday_price} ريال، نهاية الأسبوع: ${c.weekend_price} ريال، السعة: ${c.capacity} أشخاص. ${c.description||''}\n`;
  const occ = bks.filter(b => b.chalet_id === c.id && !['ملغي','منتهي'].includes(b.status||''));
  if (occ.length) {
    txt += '  التواريخ المحجوزة: ' + occ.map(b => `${b.check_in} إلى ${b.check_out}`).join('، ') + '\n';
  } else {
    txt += '  لا توجد حجوزات حالياً — متاح بالكامل.\n';
  }
}
return [{ json: { ...msg, availability: txt } }];

const p = JSON.parse(query);
const token = $('دخول نظام الإدارة').first().json.token;
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://chalet-admin-rtl.emergent.host/api/bookings',
  headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
  body: { guest_name: p.guest_name, mobile: p.mobile, status: 'استفسار',
    booking_items: [{ chalet_id: p.chalet_id, check_in: p.check_in, check_out: p.check_out }] },
  json: true
});
return JSON.stringify({ نجاح: true, رقم_الحجز: res.booking_code, الإجمالي: res.total_price });
